CREATE DATABASE RetailAnalytics;
USE RetailAnalytics;
CREATE TABLE dim_Calendar (
    date_key         DATE         NOT NULL,
    year             INT     NOT NULL,
    quarter          INT      NOT NULL,
    month            INT      NOT NULL,
    month_name       VARCHAR(10)  NOT NULL,
    week_of_year     INT      NOT NULL,
    day_of_month     INT      NOT NULL,
    day_name         VARCHAR(10)  NOT NULL,
    is_weekend       INT          NOT NULL,
    CONSTRAINT PK_Calendar PRIMARY KEY (date_key)
);
CREATE TABLE dim_Region (
    region_id       INT          NOT NULL,
    sales_district  VARCHAR(60)  NOT NULL,
    sales_region    VARCHAR(60)  NOT NULL,
    CONSTRAINT PK_Region PRIMARY KEY (region_id)
);
CREATE TABLE dim_Products (
    product_id           INT             NOT NULL,
    product_brand        VARCHAR(60)     NOT NULL,
    product_name         VARCHAR(120)    NOT NULL,
    product_sku          VARCHAR(30)     NOT NULL,
    product_retail_price DECIMAL(10,2)   NOT NULL,
    product_cost         DECIMAL(10,2)   NOT NULL,
    product_weight       DECIMAL(10,2)   NULL,
    recyclable           INT      NULL,
    low_fat              INT      NULL,
    CONSTRAINT PK_Products PRIMARY KEY (product_id)
);
CREATE TABLE dim_Customers (
    customer_id              INT           NOT NULL,
    customer_acct_num        VARCHAR(20)   NULL,
    first_name               VARCHAR(50)   NOT NULL,
    last_name                VARCHAR(50)   NOT NULL,
    customer_address         VARCHAR(150)  NULL,
    customer_city            VARCHAR(60)   NULL,
    customer_state_province  VARCHAR(50)   NULL,
    customer_postal_code     VARCHAR(20)   NULL,
    customer_country         VARCHAR(30)   NULL,
    birthdate                DATE          NULL,
    marital_status           CHAR(1)       NULL,
    yearly_income            VARCHAR(20)   NULL,
    gender                   CHAR(1)       NULL,
    total_children           INT       NULL,
    num_children_at_home     INT       NULL,
    education                VARCHAR(50)   NULL,
    acct_open_date           DATE          NULL,
    member_card              VARCHAR(20)   NULL,
    occupation               VARCHAR(50)   NULL,
    homeowner                CHAR(1)       NULL,
    CONSTRAINT PK_Customers PRIMARY KEY (customer_id)
);
CREATE TABLE dim_Stores (
    store_id             INT          NOT NULL,
    region_id            INT          NOT NULL,
    store_type           VARCHAR(40)  NOT NULL,
    store_name           VARCHAR(60)  NOT NULL,
    store_street_address VARCHAR(150) NULL,
    store_city           VARCHAR(60)  NULL,
    store_state          VARCHAR(50)  NULL,
    store_country        VARCHAR(30)  NULL,
    store_phone          VARCHAR(20)  NULL,
    first_opened_date    DATE         NULL,
    last_remodel_date    DATE         NULL,
    total_sqft           INT          NULL,
    grocery_sqft         INT          NULL,
    CONSTRAINT PK_Stores PRIMARY KEY (store_id),
    CONSTRAINT FK_Stores_Region FOREIGN KEY (region_id)
        REFERENCES dim_Region(region_id)
);
CREATE TABLE fact_Sales (
    sale_id          INT   NOT NULL AUTO_INCREMENT,
    transaction_date DATE               NOT NULL,
    stock_date       DATE               NULL,
    product_id       INT                NOT NULL,
    customer_id      INT                NOT NULL,
    store_id         INT                NOT NULL,
    quantity         INT                NOT NULL,
    CONSTRAINT PK_Sales PRIMARY KEY (sale_id),
    CONSTRAINT FK_Sales_Product  FOREIGN KEY (product_id)  REFERENCES dim_Products(product_id),
    CONSTRAINT FK_Sales_Customer FOREIGN KEY (customer_id) REFERENCES dim_Customers(customer_id),
    CONSTRAINT FK_Sales_Store    FOREIGN KEY (store_id)    REFERENCES dim_Stores(store_id),
    CONSTRAINT FK_Sales_Calendar FOREIGN KEY (transaction_date) REFERENCES dim_Calendar(date_key)
);
CREATE TABLE fact_Returns (
    return_id    INT  NOT NULL AUTO_INCREMENT,
    return_date  DATE               NOT NULL,
    product_id   INT                NOT NULL,
    store_id     INT                NOT NULL,
    quantity     INT                NOT NULL,
    CONSTRAINT PK_Returns PRIMARY KEY (return_id),
    CONSTRAINT FK_Returns_Product FOREIGN KEY (product_id) REFERENCES dim_Products(product_id),
    CONSTRAINT FK_Returns_Store   FOREIGN KEY (store_id)   REFERENCES dim_Stores(store_id)
);


